class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.documents = [[] for _ in range(n)]

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            if self.rank[rootX] > self.rank[rootY]:
                self.parent[rootY] = rootX
                self.documents[rootX].extend(self.documents[rootY])
            elif self.rank[rootX] < self.rank[rootY]:
                self.parent[rootX] = rootY
                self.documents[rootY].extend(self.documents[rootX])
            else:
                self.parent[rootY] = rootX
                self.documents[rootX].extend(self.documents[rootY])
                self.rank[rootX] += 1

    def add_document(self, x, doc_id):
        root = self.find(x)
        self.documents[root].append(doc_id)

    def check_document(self, x, doc_id):
        root = self.find(x)
        return doc_id in self.documents[root]

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    m = int(data[index + 1])
    index += 2

    uf = UnionFind(n)
    doc_id = 0
    results = []

    for _ in range(m):
        t = int(data[index])
        index += 1
        if t == 1:
            x = int(data[index]) - 1
            y = int(data[index + 1]) - 1
            index += 2
            uf.union(x, y)
        elif t == 2:
            x = int(data[index]) - 1
            index += 1
            doc_id += 1
            uf.add_document(x, doc_id)
        elif t == 3:
            x = int(data[index]) - 1
            doc_id_to_check = int(data[index + 1])
            index += 2
            if uf.check_document(x, doc_id_to_check):
                results.append("YES")
            else:
                results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
